-- Perfumes masculinos e femininos (inclui as categorias Perfumes Árabes e Farmácia). A primeira instrução libera as categorias novas.
-- ATENÇÃO: os preços são o valor de ATACADO do Atacado Connect (US$ x cotação 6,05), SEM a sua margem.
-- Ajuste os preços no /admin (ou o campo price neste arquivo) antes de vender.
-- Cole no SQL Editor do Supabase e clique em Run. Rodar de novo sobrescreve edições feitas no admin.

-- Libera as categorias 'arabes' (Perfumes Árabes) e 'farmacia' (Farmácia) na tabela de produtos.
-- Rode ANTES de importar os perfumes. Pode rodar mais de uma vez.
ALTER TABLE public.products DROP CONSTRAINT IF EXISTS products_category_check;
ALTER TABLE public.products
  ADD CONSTRAINT products_category_check
  CHECK (category IN ('farmacia', 'perfumes', 'arabes', 'bebidas', 'beleza', 'eletronicos', 'smartphones', 'acessorios'));

